import{_ as n,a0 as o,w as r,s as h,ao as p,I as l,x as t,a1 as i,A as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const S=JSON.parse('{"title":"用 Starship 定製你的 shell 提示符 | LCTT x X-CMD","titleTemplate":false,"description":"用 Starship 定製你的 shell 提示符 | LCTT (202202) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"用 Starship 定製你的 shell 提示符 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"用 Starship 定製你的 shell 提示符 | LCTT (202202) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202202/20220207 Customize your shell prompt with Starship","title":"用 Starship 定製你的 shell 提示符","tag":"202202","desc":""},"relativePath":"202202/20220207 Customize your shell prompt with Starship.md","filePath":"[post].md"}'),d={name:"202202/20220207 Customize your shell prompt with Starship.md"};function u(g,s,b,k,c,m){const a=o("Link");return r(),h("div",null,[s[18]||(s[18]=p(`<h1 id="用-starship-定製你的-shell-提示符" tabindex="-1">用 Starship 定製你的 shell 提示符 <a class="header-anchor" href="#用-starship-定製你的-shell-提示符" aria-label="Permalink to “用 Starship 定製你的 shell 提示符”">​</a></h1><blockquote><p>控制你的提示符，讓你需要的所有信息觸手可及。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202202/14/232227pkh7bxi1a9asbfd5.jpg" alt=""></p><p>沒有什麼比我忘記在我的 Git 倉庫中 <code>git add</code> 文件更讓我惱火的了。我在本地測試，提交，然後推送，卻發現在持續集成階段失敗了。更糟糕的是，我在 <code>main</code> 分支而不是特性分支上，並不小心推送到它。最好的情況是，因為分支保護而失敗，我需要做一些操作才能把改動推送到一個分支。更糟糕的是，我沒有正確配置分支保護，不小心直接推送到了 <code>main</code> 分支。</p><p>如果這些信息能在提示中直接獲得，那不是很好嗎？</p><p>在提示符中甚至還有更多有用的信息。雖然 Python 虛擬環境的名稱在提示符中，但虛擬環境的 Python 版本卻不在提示符中。</p><p>可以仔細地將 <code>PS1</code> 環境變量配置為所有相關的信息。這可能會變得很長，很煩人，而且調試起來並不簡單。</p><p>這就是 Starship 被設計來解決的問題。</p><h3 id="安裝-starship" tabindex="-1">安裝 Starship <a class="header-anchor" href="#安裝-starship" aria-label="Permalink to “安裝 Starship”">​</a></h3><p>Starship 的初始設置只需要兩個步驟：安裝並配置你的 shell。安裝可以很簡單：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ curl -fsSL https://starship.rs/install.sh</span></span></code></pre></div><p>閲讀安裝腳本，確保你理解它的作用，然後讓它可執行並運行它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ chmod +x install.sh</span></span>
<span class="line"><span>$ ./install.sh</span></span></code></pre></div><p>還有其他的安裝方法，在其網站上有介紹。你可以在構建鏡像的步驟中設置虛擬機或容器。</p><h3 id="配置-starship" tabindex="-1">配置 Starship <a class="header-anchor" href="#配置-starship" aria-label="Permalink to “配置 Starship”">​</a></h3><p>下一步是配置你的 shell 來使用它。要一次性嘗試，假設 shell 是 <code>bash</code> 或 <code>zsh</code>，請運行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ eval &quot;$(starship init $(basename $SHELL))&quot;</span></span></code></pre></div><p>你的提示符立即改變：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>localhost in myproject on  master</span></span>
<span class="line"><span>&gt;</span></span></code></pre></div><p>如果你喜歡你所看到的，把 <code>eval &quot;$(starship init $(basename $SHELL))&quot;</code> 添加到你的 shell 的 <code>rc</code> 文件中，使其永久化。</p><h3 id="自定義-starship" tabindex="-1">自定義 Starship <a class="header-anchor" href="#自定義-starship" aria-label="Permalink to “自定義 Starship”">​</a></h3>`,21)),l("p",null,[s[1]||(s[1]=t("默認安裝假定你可以安裝“電腦迷字體”，例如 ",-1)),i(a,{href:"https://github.com/belluzj/fantasque-sans"},{default:e(()=>[...s[0]||(s[0]=[t("Fantasque Sans Mono",-1)])]),_:1}),s[2]||(s[2]=t("。 特別是，你需要一種帶有來自 Unicode 的“私有實現”部分的字形的字體。",-1))]),s[19]||(s[19]=p(`<p>這在控制終端時非常有效，但有時，終端的配置並不容易。例如，當使用一些瀏覽器內的 shell 抽象時，配置瀏覽器的字體可能是不太容易的。</p><p>該碼位的最大用户是 Git 集成，它使用一個特殊的自定義符號來表示“分支”。禁用它可以通過使用文件 <code>~/.config/starship.toml</code> 來配置 <code>starship.rs</code>。</p><p>禁用分支符號是通過配置 <code>git_branch</code> 部分的 <code>format</code> 變量完成的：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[git_branch]</span></span>
<span class="line"><span>format = &quot;on [$branch]($style) &quot;</span></span></code></pre></div><p><code>starship.rs</code> 的一個好處是，改變配置會立即生效。保存文件，按下<strong>回車</strong>，看看字體是否符合預期。</p><p>還可以配置提示符中不同部分的顏色。例如，如果 Python 部分的亮黃色在白色背景上有點難看，你可以配置為藍色：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[python]</span></span>
<span class="line"><span>style = &quot;blue bold&quot;</span></span></code></pre></div><p>許多語言都有配置支持，包括 Go、.NET 和 JavaScript。還支持顯示命令的持續時間（只針對耗時超過閾值的命令）等。</p><h3 id="控制提示符" tabindex="-1">控制提示符 <a class="header-anchor" href="#控制提示符" aria-label="Permalink to “控制提示符”">​</a></h3><p>控制你的提示符，讓你需要的所有信息觸手可及。安裝 Starship，讓它為你工作，並享受吧！</p><hr>`,11)),l("p",null,[s[4]||(s[4]=t("via: ",-1)),i(a,{href:"https://opensource.com/article/22/2/customize-prompt-starship"},{default:e(()=>[...s[3]||(s[3]=[t("https://opensource.com/article/22/2/customize-prompt-starship",-1)])]),_:1})]),l("p",null,[s[9]||(s[9]=t("作者：",-1)),i(a,{href:"https://opensource.com/users/moshez"},{default:e(()=>[...s[5]||(s[5]=[t("Moshe Zadka",-1)])]),_:1}),s[10]||(s[10]=t(" 選題：",-1)),i(a,{href:"https://github.com/lujun9972"},{default:e(()=>[...s[6]||(s[6]=[t("lujun9972",-1)])]),_:1}),s[11]||(s[11]=t(" 譯者：",-1)),i(a,{href:"https://github.com/geekpi"},{default:e(()=>[...s[7]||(s[7]=[t("geekpi",-1)])]),_:1}),s[12]||(s[12]=t(" 校對：",-1)),i(a,{href:"https://github.com/wxy"},{default:e(()=>[...s[8]||(s[8]=[t("wxy",-1)])]),_:1})]),l("p",null,[s[15]||(s[15]=t("本文由 ",-1)),i(a,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...s[13]||(s[13]=[t("LCTT",-1)])]),_:1}),s[16]||(s[16]=t(" 原創編譯，",-1)),i(a,{href:"https://linux.cn/"},{default:e(()=>[...s[14]||(s[14]=[t("Linux中國",-1)])]),_:1}),s[17]||(s[17]=t(" 榮譽推出",-1))])])}const y=n(d,[["render",u]]);export{S as __pageData,y as default};
